def diameter(root):
    return solve(root)[1]


def solve(node):
    """Return (height, best diameter in this subtree)."""
    if node is None:
        return 0, 0
    lh, ld = solve(node.left)
    rh, rd = solve(node.right)
    here = lh + rh
    return 1 + max(lh, rh), max(ld, rd, here)
